import requests

# Search for other IMF commodity data files in Wayback
queries = [
    "https://web.archive.org/cdx/search/cdx?url=imf.org/-/media/Files/Research/CommodityPrices/*&output=json&limit=30&fl=timestamp,original,statuscode,mimetype&filter=statuscode:200&sort=reverse",
    "https://web.archive.org/cdx/search/cdx?url=imf.org/external/np/res/commod/*&output=json&limit=30&fl=timestamp,original,statuscode,mimetype&filter=statuscode:200&sort=reverse",
]

for q in queries:
    try:
        resp = requests.get(q, timeout=30, headers={'User-Agent': 'Mozilla/5.0'})
        if resp.text.strip():
            import json
            data = json.loads(resp.text)
            print(f"Query results ({len(data)-1} entries):")
            for row in data[1:]:
                print(f"  {row}")
        print()
    except Exception as e:
        print(f"Error: {e}")
